approve_offsite(uuid,timestamp with time.def:
CREATE OR REPLACE FUNCTION public.approve_offsite(p_shift_id uuid, p_checked_in_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_checked_out_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept uuid := public.my_department_id();
  v_me   uuid := public.my_member_id();
  v_row  public.station_presence;
  v_in   timestamptz;
  v_out  timestamptz;
begin
  if not public.is_leadership() then
    raise exception 'Not authorized';
  end if;

  select * into v_row from public.station_presence
   where id = p_shift_id and department_id = v_dept
   for update;

  if not found then
    raise exception 'That shift was not found in your department.';
  end if;
  if v_row.kind <> 'offsite' then
    raise exception 'That is not an off-site shift.';
  end if;
  if v_row.approved_at is not null then
    raise exception 'That off-site time has already been reviewed.';
  end if;
  if v_row.checked_out_at is null then
    raise exception 'That shift is still open — it can be approved once the member checks out.';
  end if;

  v_in  := coalesce(p_checked_in_at,  v_row.checked_in_at);
  v_out := coalesce(p_checked_out_at, v_row.checked_out_at);

  if v_out <= v_in then
    raise exception 'The end time must be after the start time.';
  end if;
  if v_out > now() then
    raise exception 'The end time cannot be in the future.';
  end if;

  update public.station_presence
     set checked_in_at  = v_in,
         checked_out_at = v_out,
         auto_closed    = false,   -- the officer has confirmed the window
         approved_at    = now(),
         approved_by    = v_me
   where id = p_shift_id;
end;
$function$

close_open_shift(uuid,timestamp with tim.def:
CREATE OR REPLACE FUNCTION public.close_open_shift(p_shift_id uuid, p_checked_out_at timestamp with time zone)
 RETURNS TABLE(shift_id uuid, checked_in_at timestamp with time zone, checked_out_at timestamp with time zone, auto_closed boolean, verified boolean, hours numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept uuid := public.my_department_id();
  v_row  public.station_presence;
begin
  if not public.is_dept_admin() then
    raise exception 'Not authorized';
  end if;
  if p_checked_out_at is null then
    raise exception 'Enter the time the member actually left.';
  end if;

  select * into v_row
    from public.station_presence
   where id = p_shift_id and department_id = v_dept
   for update;

  if not found then
    raise exception 'That shift was not found in your department.';
  end if;
  -- Already closed: never overwrite. Whoever set it — the sweeper, a departure
  -- event, another admin — recorded something, and silently replacing it would
  -- destroy the only record that it happened.
  if v_row.checked_out_at is not null then
    raise exception 'That shift is already closed.';
  end if;
  if p_checked_out_at <= v_row.checked_in_at then
    raise exception 'The out-time must be after the member checked in.';
  end if;
  if p_checked_out_at > now() then
    raise exception 'The out-time cannot be in the future.';
  end if;

  update public.station_presence
     set checked_out_at = p_checked_out_at,
         auto_closed    = false
   where id = p_shift_id
  returning * into v_row;

  return query
    select v_row.id,
           v_row.checked_in_at,
           v_row.checked_out_at,
           v_row.auto_closed,
           v_row.verified,
           round((extract(epoch from (v_row.checked_out_at - v_row.checked_in_at)) / 3600.0)::numeric, 2);
end;
$function$

confirm_on_station(uuid,double precision.def:
CREATE OR REPLACE FUNCTION public.confirm_on_station(p_shift_id uuid, p_lat double precision, p_lng double precision, p_accuracy double precision)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row   public.station_presence;
  v_slat  double precision;
  v_slng  double precision;
  v_srad  integer;
  v_ok    boolean;
begin
  if p_lat is null or p_lng is null then
    return false;                      -- no fix, nothing to confirm
  end if;

  select * into v_row from public.station_presence where id = p_shift_id;
  if not found then return false; end if;

  -- Only an OPEN, non-off-site shift is a candidate. See the header for both.
  if v_row.checked_out_at is not null then return false; end if;
  if v_row.kind = 'offsite'            then return false; end if;

  -- Already true: the latch has nothing left to do. Reported as success, because
  -- from the caller's point of view the shift IS confirmed.
  if coalesce(v_row.verified, false) then return true; end if;

  -- The house this shift was attributed to, falling back to the department pin
  -- exactly as station_check_in does — same two-step, so "on station" means the
  -- same thing on every path.
  if v_row.station_id is not null then
    select s.lat, s.lng, s.radius_m into v_slat, v_slng, v_srad
      from stations s where s.id = v_row.station_id;
  end if;
  if v_slat is null or v_slng is null then
    select d.station_lat, d.station_lng, d.station_radius_m
      into v_slat, v_slng, v_srad
      from departments d where d.id = v_row.department_id;
  end if;
  if v_slat is null or v_slng is null then
    return false;                      -- nothing pinned to measure against
  end if;

  v_ok := public.is_at_point(v_slat, v_slng, v_srad, p_lat, p_lng, p_accuracy);
  if not v_ok then
    return false;                      -- NOT inside. Changes nothing. Never writes false.
  end if;

  update public.station_presence
     set verified = true
   where id = p_shift_id
     and verified is distinct from true;   -- belt: the write itself is one-way

  return true;
end;
$function$

dept_member_iso_hours_by_month(uuid,time.def:
CREATE OR REPLACE FUNCTION public.dept_member_iso_hours_by_month(p_member_id uuid, p_starts timestamp with time zone[], p_ends timestamp with time zone[])
 RETURNS TABLE(idx integer, credited numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  n integer := coalesce(array_length(p_starts, 1), 0);
begin
  if p_member_id is null then
    raise exception 'A member is required.';
  end if;
  if n <> coalesce(array_length(p_ends, 1), 0) then
    raise exception 'Starts and ends must be the same length.';
  end if;
  if n > 24 then
    raise exception 'At most 24 windows per call.';
  end if;
  -- idx is 1-based, matching the input arrays. Every window gets a row, even an
  -- empty one (credited 0), so the client never mistakes a missing row for a
  -- failed read.
  return query
  select i,
         coalesce((select h.iso_total_hours
                     from public.dept_iso_hours(p_starts[i], p_ends[i]) h
                    where h.member_id = p_member_id), 0)::numeric
    from generate_series(1, n) as i
   order by i;
end;
$function$

drill_window_presence(uuid).def:
CREATE OR REPLACE FUNCTION public.drill_window_presence(p_session_id uuid)
 RETURNS TABLE(member_id uuid, member_name text, first_in timestamp with time zone, last_out timestamp with time zone, still_open boolean, auto_closed boolean, on_roll boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 R1/R2 — who was ON STANDBY while this drill ran: the roll-call prefill's suggestions. READ ONLY.
    -- Window start = (date + start_time) read in America/Chicago — the same expression attested_training uses; window
    -- length = the drill's duration_min, else the flat 90. No start time -> no window -> no rows. The caller decides
    -- (pre-ticked suggestions); confirming writes plain session_attendance via the existing roster path, never this.
    declare
      v_dept  uuid := public.my_department_id();
      s       public.training_sessions%rowtype;
      v_start timestamptz; v_end timestamptz;
    begin
      if v_dept is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can see who was on station.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s.start_time is null then return; end if;
      v_start := (s."date" + s.start_time) at time zone 'America/Chicago';
      v_end   := v_start + make_interval(mins => coalesce(s.duration_min, 90));
      return query
        select sp.member_id, m.name, min(sp.checked_in_at), max(sp.checked_out_at),
               bool_or(sp.checked_out_at is null), bool_or(sp.auto_closed),
               exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = sp.member_id)
          from public.station_presence sp
          join public.members m on m.id = sp.member_id and m.department_id = s.department_id
         where sp.department_id = s.department_id
           and sp.kind = 'standby'
           and sp.checked_in_at < v_end
           and coalesce(sp.checked_out_at, now()) > v_start
         group by sp.member_id, m.name
         order by m.name;
    end;
    $function$

geofence_arrive(double precision,double.def:
CREATE OR REPLACE FUNCTION public.geofence_arrive(p_lat double precision, p_lng double precision, p_accuracy double precision DEFAULT NULL::double precision, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_station_id uuid DEFAULT NULL::uuid)
 RETURNS station_presence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member   uuid := public.my_member_id();
  v_dept     uuid := public.my_department_id();
  v_enabled  boolean;
  v_lat      double precision;   -- the DEPARTMENT pin, still the fallback
  v_lng      double precision;
  v_radius   integer;
  v_station  uuid;               -- the RESOLVED house, or null for arm 3
  v_slat     double precision;   -- that house's pin
  v_slng     double precision;
  v_srad     integer;
  v_verified boolean;
  v_at       timestamptz := coalesce(p_at, now());
  v_row      public.station_presence;
begin
  if v_member is null or v_dept is null then
    raise exception 'We could not match your login to a member record.';
  end if;

  select geofence_enabled, station_lat, station_lng, station_radius_m
    into v_enabled, v_lat, v_lng, v_radius
    from public.departments where id = v_dept;

  if not coalesce(v_enabled, false) then
    raise exception 'Automatic arrival is not switched on for your department.';
  end if;

  -- the device's clock is not ours to trust
  if v_at > now() + interval '5 minutes' then
    raise exception 'That arrival is timestamped in the future — check the device clock.';
  end if;
  if v_at > now() then
    v_at := now();                                  -- ordinary drift; clamp rather than refuse
  end if;
  if v_at < now() - interval '30 days' then
    raise exception 'That arrival is more than 30 days old and was not recorded.';
  end if;

  -- already on the clock? hand back that row. Never open a second session.
  select * into v_row from public.station_presence
   where member_id = v_member
     and checked_out_at is null
     and kind in ('standby','offsite')
   order by checked_in_at desc limit 1;
  if found then return v_row; end if;

  /* ALREADY RECORDED — OPEN OR CLOSED. Carried over from g4l1 unchanged; without
     it, replay duplicates every ordinary completed shift on the next app open and
     inflates exactly the hours ISO and LOSAP are counted from. Matching on
     ARRIVAL TIME is what makes a replayed event land on the row it already
     created. */
  select * into v_row from public.station_presence
   where member_id = v_member
     and source = 'gps_geofence'                     -- only rows this function created
     and kind in ('standby','offsite')
     and checked_in_at between v_at - interval '2 minutes' and v_at + interval '2 minutes'
   order by abs(extract(epoch from (checked_in_at - v_at)))   -- the closest match, not merely the newest
   limit 1;
  if found then return v_row; end if;

  /* ALREADY COVERED BY A RECORDED SHIFT — the guard the two above could not be.

     The first returns an OPEN row; by the time a late event lands the row is
     usually closed. The second catches a redelivery of the SAME event within two
     minutes. What actually cost hours was neither: a fence flapping at its
     boundary fired a SECOND, GENUINE DWELL minutes after the first, and that
     event was delivered late — 69 minutes late on 2026-08-31, landing 38 minutes
     after the shift it fell inside had already closed. Observed arrival gaps were
     8m46s, 4m05s and 2m03s; all three sailed past the two-minute window and each
     inserted a row covering time already credited.

     CONTAINMENT, NOT A WIDER WINDOW. Nine minutes of slack would begin rejecting
     real re-entries. An arrival that falls INSIDE a shift already on the books is,
     by definition, a re-trigger of presence already recorded. A genuine return
     happens AFTER the previous shift closed and therefore lands outside every
     range — so this cannot swallow one.

     NOT RESTRICTED BY SOURCE, unlike the guard above it. A late fence arrival
     landing inside a MANUAL shift double-counts identically, and the "already on
     the clock" guard is source-agnostic for exactly that reason.

     RETURNS THE COVERING ROW rather than raising: the same contract as the two
     guards above, and the caller reads a returned row as "you are on the clock",
     which is true. */
  select * into v_row from public.station_presence
   where member_id = v_member
     and kind in ('standby','offsite')
     and tstzrange(checked_in_at, coalesce(checked_out_at, 'infinity')) @> v_at
   order by checked_in_at desc limit 1;
  if found then return v_row; end if;

  /* ── D2a: WHICH HOUSE ──────────────────────────────────────────────────────
     ARM 1 — the phone's hint, validated. The department check is the security
     boundary: without it a device could attribute its arrival to any station row
     in the system, including another department's. */
  if p_station_id is not null then
    select s.id, s.lat, s.lng, s.radius_m
      into v_station, v_slat, v_slng, v_srad
      from stations s
     where s.id = p_station_id
       and s.department_id = v_dept
       and s.is_active;
  end if;

  /* ARM 2 — no usable hint, so re-derive it from the coordinates. The nearest
     active pinned house whose OWN radius contains the fix. Accuracy is not
     passed: see the header — this is routing, not verification. */
  if v_station is null and p_lat is not null and p_lng is not null then
    select s.id, s.lat, s.lng, s.radius_m
      into v_station, v_slat, v_slng, v_srad
      from stations s
     where s.department_id = v_dept
       and s.is_active
       and s.lat is not null
       and s.lng is not null
       and public.is_at_point(s.lat, s.lng, s.radius_m, p_lat, p_lng, null)
     order by 6371000 * 2 * asin(sqrt(
                power(sin(radians(p_lat - s.lat) / 2), 2)
                + cos(radians(s.lat)) * cos(radians(p_lat)) * power(sin(radians(p_lng - s.lng) / 2), 2)))
     limit 1;
  end if;

  /* ARM 3 — v_station stays null. The insert names station_id anyway, and
     set_default_station_id() only fills when NULL, so the row is stamped exactly
     as it is today. Nothing errors. */

  -- VERIFY against the resolved house when it carries a pin; otherwise the
  -- department, which is what the live body does for every arrival today.
  if v_station is not null and v_slat is not null and v_slng is not null then
    v_verified := public.is_at_point(v_slat, v_slng, v_srad, p_lat, p_lng, p_accuracy);
  else
    v_verified := public.is_at_point(v_lat, v_lng, v_radius, p_lat, p_lng, p_accuracy);
  end if;

  insert into public.station_presence
    (department_id, member_id, verified, source, kind, checked_in_at, station_id)
  values
    (v_dept, v_member, v_verified, 'gps_geofence', 'standby', v_at, v_station)
  returning * into v_row;

  return v_row;
end;
$function$

geofence_confirm_presence(double precisi.def:
CREATE OR REPLACE FUNCTION public.geofence_confirm_presence(p_lat double precision, p_lng double precision, p_accuracy double precision DEFAULT NULL::double precision)
 RETURNS station_presence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member uuid := public.my_member_id();
  v_row    public.station_presence;
begin
  if v_member is null then
    raise exception 'We could not match your login to a member record.';
  end if;

  -- The caller's OWN open shift. Off-site is excluded here as well as in the
  -- helper: not because one check is insufficient, but because a reader of this
  -- function should not have to open another one to learn that off-site is out.
  select * into v_row from public.station_presence
   where member_id = v_member
     and checked_out_at is null
     and kind <> 'offsite'
   order by checked_in_at desc
   limit 1;

  if not found then
    return null;                       -- nothing open; not an error
  end if;

  perform public.confirm_on_station(v_row.id, p_lat, p_lng, p_accuracy);

  -- Re-read so the caller sees the latched value rather than the pre-update copy.
  select * into v_row from public.station_presence where id = v_row.id;
  return v_row;
end;
$function$

member_check_in(uuid,text,double precisi.def:
CREATE OR REPLACE FUNCTION public.member_check_in(p_session_id uuid, p_token text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_accuracy double precision DEFAULT NULL::double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session  public.training_sessions%ROWTYPE;
  v_member   uuid := public.my_member_id();
  v_dept     uuid := public.my_department_id();
  v_recorded boolean := false;
  v_verified boolean := false;
  v_pinned   boolean := true;   -- fail closed if the department row does not resolve
BEGIN
  IF v_member IS NULL OR v_dept IS NULL THEN
    RAISE EXCEPTION 'We could not match your login to a member record.';
  END IF;

  SELECT * INTO v_session FROM public.training_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That training session was not found.';
  END IF;

  IF v_session.department_id IS DISTINCT FROM v_dept THEN
    RAISE EXCEPTION 'That session is not in your department.';
  END IF;

  IF v_session.done THEN
    RAISE EXCEPTION 'This session is complete — attendance is locked.';
  END IF;
  -- B4C:slice7 — nobody checks in to a cancelled session.
  IF v_session.status = 'cancelled' THEN
    RAISE EXCEPTION 'CANCELLED: this session was cancelled — there is nothing to check in to.';
  END IF;

  -- ---- ADDED: the sign-in must be OPEN, not merely hold a matching code ----
  -- Without this, "is this sign-in open?" is answered indirectly, by whether
  -- some other function remembered to clear the token when closing. That is an
  -- invariant maintained by one writer and breakable by any direct UPDATE.
  IF NOT coalesce(v_session.signin_open, false) THEN
    RAISE EXCEPTION 'Sign-in for this session has closed — ask your training officer to reopen it.';
  END IF;
  -- ---- END ADDED ----

  IF v_session.signin_token IS NULL OR v_session.signin_token <> p_token THEN
    RAISE EXCEPTION 'Invalid or expired sign-in code — scan the current QR.';
  END IF;

  INSERT INTO public.session_attendance (department_id, session_id, member_id, checked_in_at)
  VALUES (v_dept, p_session_id, v_member, now())
  ON CONFLICT (session_id, member_id) DO NOTHING;
  v_recorded := FOUND;

  -- ---- CHANGED IN C3: branch on the FLAG, not on whether coordinates exist ----
  IF v_session.is_offsite THEN
    IF v_session.location_lat IS NOT NULL AND v_session.location_lng IS NOT NULL THEN
      v_verified := public.is_at_point(
        v_session.location_lat, v_session.location_lng,
        coalesce(v_session.location_radius_m,
                 (SELECT station_radius_m FROM public.departments WHERE id = v_dept),
                 400),
        p_lat, p_lng, p_accuracy);
    ELSE
      -- Off-site, but nobody has captured where. NEVER fall back to the station:
      -- they are not there. No clock; attendance above still stands.
      v_verified := false;
    END IF;
    v_pinned := true;   -- an off-site session is always "pinned" for gate purposes
  ELSE
    v_verified := public.is_at_station(v_dept, p_lat, p_lng, p_accuracy);
    SELECT (station_lat IS NOT NULL AND station_lng IS NOT NULL)
      INTO v_pinned
      FROM public.departments
     WHERE id = v_dept;
  END IF;
  -- ---- END CHANGED BLOCK ----

  IF v_verified OR NOT v_pinned THEN
    INSERT INTO public.station_presence (department_id, member_id, verified, source, kind, session_id)
    VALUES (v_dept, v_member, v_verified, 'geo', 'training', p_session_id)
    ON CONFLICT (member_id, session_id) WHERE kind = 'training' AND session_id IS NOT NULL DO NOTHING;
  END IF;

  IF v_recorded THEN RETURN 'recorded'; ELSE RETURN 'already'; END IF;
END;
$function$

offsite_check_in(text,double precision,d.def:
CREATE OR REPLACE FUNCTION public.offsite_check_in(p_label text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_accuracy double precision DEFAULT NULL::double precision)
 RETURNS station_presence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member uuid := public.my_member_id();
  v_dept   uuid := public.my_department_id();
  v_label  text := nullif(btrim(coalesce(p_label, '')), '');
  v_row    public.station_presence;
begin
  if v_member is null or v_dept is null then
    raise exception 'We could not match your login to a member record.';
  end if;
  if v_label is null then
    raise exception 'Say what the work is before checking in (for example, "Memorial Day parade").';
  end if;

  -- already on an off-site shift -> hand back the same row, do not open a second
  select * into v_row from public.station_presence
   where member_id = v_member and kind = 'offsite' and checked_out_at is null
   order by checked_in_at desc limit 1;
  if found then return v_row; end if;

  -- cannot be on station and off-site at the same time
  update public.station_presence
     set checked_out_at = now()
   where member_id = v_member and kind = 'standby' and checked_out_at is null;

  insert into public.station_presence
    (department_id, member_id, verified, source, kind, offsite_label, location_confirmed)
  values
    (v_dept, v_member, false, 'geo', 'offsite', v_label,
     (p_lat is not null and p_lng is not null))
  returning * into v_row;

  return v_row;
end;
$function$

reject_offsite(uuid).def:
CREATE OR REPLACE FUNCTION public.reject_offsite(p_shift_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept uuid := public.my_department_id();
  v_me   uuid := public.my_member_id();
  v_row  public.station_presence;
begin
  if not public.is_leadership() then
    raise exception 'Not authorized';
  end if;

  select * into v_row from public.station_presence
   where id = p_shift_id and department_id = v_dept
   for update;

  if not found then
    raise exception 'That shift was not found in your department.';
  end if;
  if v_row.kind <> 'offsite' then
    raise exception 'That is not an off-site shift.';
  end if;
  if v_row.approved_at is not null then
    raise exception 'That off-site time has already been reviewed.';
  end if;

  update public.station_presence
     set checked_out_at = v_row.checked_in_at,   -- zero duration: kept, credits nothing
         auto_closed    = false,
         approved_at    = now(),
         approved_by    = v_me
   where id = p_shift_id;
end;
$function$

resolve_auto_closed_shift(uuid,timestamp.def:
CREATE OR REPLACE FUNCTION public.resolve_auto_closed_shift(p_shift_id uuid, p_checked_out_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept uuid := public.my_department_id();
  v_row  public.station_presence;
begin
  if not public.is_dept_admin() then          -- was is_leadership()
    raise exception 'Not authorized';
  end if;
  if p_checked_out_at is null then
    raise exception 'Enter the time the member actually left.';
  end if;

  select * into v_row
    from public.station_presence
   where id = p_shift_id and department_id = v_dept
   for update;

  if not found then
    raise exception 'That shift was not found in your department.';
  end if;
  if not v_row.auto_closed then
    raise exception 'That shift has already been reviewed.';
  end if;
  if p_checked_out_at <= v_row.checked_in_at then
    raise exception 'The out-time must be after the member checked in.';
  end if;
  if p_checked_out_at > now() then
    raise exception 'The out-time cannot be in the future.';
  end if;

  update public.station_presence
     set checked_out_at = p_checked_out_at,
         auto_closed    = false
   where id = p_shift_id;
end;
